class Solution:
    def minAreaFreeRect(self, points: List[List[int]]) -> float:
        N = len(points)

        seen = set()
        for point in points:
            seen.add(tuple(point))

        # length^2
        def length2(a, b):
            return (a[0] - b[0]) * (a[0] - b[0]) + (a[1] - b[1]) * (a[1] - b[1])

        best = 1e30
        for i in range(N):
            for j in range(N):
                if i == j:
                    continue

                lij = length2(points[i], points[j])
                for k in range(N):
                    if i == k or j == k:
                        continue

                    # given i->j line, add to k to find l
                    dx, dy = points[j][0] - points[i][0], points[j][1] - points[i][1]

                    pl = (points[k][0] + dx, points[k][1] + dy)
                    if pl not in seen:
                        continue

                    lik = length2(points[i], points[k])
                    ljk = length2(points[j], points[k])

                    lil = length2(points[i], pl)
                    ljl = length2(points[j], pl)
                    lkl = length2(points[k], pl)

                    if lij == lkl and lik == ljl and lil == ljk:
                        best = min(best, sqrt(lij * lik * lil) / sqrt(max(lij, lik, lil)))

        if best >= 1e29:
            return 0
        return best

class Solution(object):
    def leastOpsExpressTarget(self, x, target):
        return self.cost(x, target)

    def cost(self, x, val):
        if val == x:
            return 0
        elif val < x:
            # two possible states
            # either val > x / 2: we substract 1s
            state_1 = 2 * (x - val)
            # or val < x / 2: we divide once to 1 and we add enough 1s
            state_2 = 2*val - 1
            return min(state_1, state_2)
        else:
            # there is a maximum power of x that we can add
            p = int(log(val) // log(x))
            # and either x^p or x^(p+1) is the closest
            a = x**p
            b = a*x
            if b < 2*val:
                # x**(p+1) - val < val - x**p
                return min(p + self.cost(x, val - a), p + 1 + self.cost(x, b - val))
            else:
                return p + self.cost(x, val - a)
